<?php namespace Workspace;
$milestones=array_column($cal['milestones'],'title','id');$open=array_column(array_filter($cal['milestones'],fn($m)=>$m['state']==='open'),'title','id');$client=$project['kind']==='client';$canChange=!$client||$commercial;
$hidden=static function(string $act)use($p){formFields($act);echo '<input type="hidden" name="project_id" value="',h($p),'">';};
?>
<section class="panel"><h1>Управление проектом — <?= h($project['title']) ?></h1><p><a href="<?= h(url('project',['id'=>$p])) ?>">Проект и задачи</a></p><p>Базовый объём и его редакции неизменяемы. Изменения календаря вне согласования показываются отдельно от базового плана.</p>
<?php if(!$latest): ?><form method="post" class="formgrid"><?php $hidden('pm.baseline') ?><input type="hidden" name="calendar" value="<?= h(pmFingerprint($cal)) ?>"><label>Базовый объём<textarea name="scope" maxlength="4000" required></textarea></label><button>Зафиксировать базовый план</button></form><?php else: ?><h2>Базовый объём v<?= h($latest['version']) ?></h2><p class="client-text"><?= h($latest['scope']) ?></p><?php if($latest['calendar_json']!==pmJson($cal)): ?><p class="notice">Рабочий календарь отличается от последнего базового плана.</p><?php endif ?><?php endif ?></section>
<section class="panel"><h2>Рабочий календарь и зависимости</h2><table><thead><tr><th>Веха</th><th>Дата</th><th>Состояние</th><th>Предварительные вехи</th></tr></thead><tbody><?php foreach($cal['milestones'] as $m): ?><tr><td><?= h($m['title']) ?></td><td><?= h(displayDate($m['due_on'])) ?></td><td><?= h(MILESTONE_STATES[$m['state']]) ?></td><td><?php foreach($cal['edges'] as [$id,$pre]):if($id===$m['id']): ?><p><?= h($milestones[$pre].' · '.MILESTONE_STATES[$cal['milestones'][$pre]['state']]) ?></p><?php endif;endforeach ?></td></tr><?php endforeach ?></tbody></table>
<?php if(count($milestones)>1): ?><form method="post" class="formgrid"><?php $hidden('pm.dependency') ?><input type="hidden" name="calendar" value="<?= h(pmFingerprint($cal)) ?>"><label>Зависимая веха<select name="milestone_id"><?php selectOptions($milestones) ?></select></label><label>Предварительная веха<select name="prerequisite_id"><?php selectOptions($milestones) ?></select></label><button name="mode" value="add">Добавить зависимость</button><button name="mode" value="remove" class="secondary">Удалить зависимость</button></form><?php endif ?></section>
<?php if($latest&&$canChange&&(!$client||$orders)): ?><section class="panel"><h2>Запрос на изменение</h2><p>Новый срок распространяется только на зависимые вехи, сроки которых иначе окажутся раньше предварительной. Сроки задач не меняются автоматически. Проверьте согласуемый календарь перед применением.</p><form method="post" class="formgrid"><?php $hidden('pm.propose') ?><input type="hidden" name="baseline" value="<?= h($latest['version']) ?>"><input type="hidden" name="calendar" value="<?= h(pmFingerprint($cal)) ?>"><label>Название<input name="title" maxlength="180" required></label><label>Новая редакция объёма<textarea name="scope" maxlength="4000" required><?= h($latest['scope']) ?></textarea></label><label>Внутреннее основание<textarea name="reason" maxlength="4000" required></textarea></label><label>Изменяемая веха<select name="milestone_id"><?php selectOptions([''=>'Без изменения срока']+$open) ?></select></label><label>Новый срок<input type="date" name="due_on"></label><?php if($client): ?><label>Принятый заказ<select name="order_id"><?php foreach($orders as $o): ?><option value="<?= h($o['id']) ?>"><?= h($o['title'].' · '.$o['currency']) ?></option><?php endforeach ?></select></label><label>Доплата без налогов (0 допустим)<input name="amount" inputmode="decimal" value="0" required></label><label>Срок оплаты<input type="date" name="payment_due" min="<?= h(gmdate('Y-m-d')) ?>" required></label><label><input type="checkbox" name="share" value="yes" required> Название, новый объём, доплата и изменения дат разрешены для клиента (будут опубликованы при создании)</label><?php endif ?><button>Создать запрос</button></form></section><?php elseif($client&&!$commercial): ?><p class="notice">Коммерческий запрос создаёт и применяет владелец организации.</p><?php elseif($client&&!$orders): ?><p class="notice">Для запроса нужен принятый клиентский заказ.</p><?php endif ?>
<section class="panel"><h2>Запросы на изменение</h2><?php foreach($changes as $r): $before=json_decode($r['calendar_before'],true,512,JSON_THROW_ON_ERROR);$after=json_decode($r['calendar_after'],true,512,JSON_THROW_ON_ERROR);$dates=pmDateChanges($before,$after); ?><details><summary>#<?= h($r['number'].' · '.$r['title'].' · '.PM_STATES[$r['status']]) ?></summary><p>Создано сотрудником #<?= h($r['actor_id']) ?> · <?= h(gmdate('Y-m-d H:i',(int)$r['created_at'])) ?> UTC</p><p>Основание: <?= h($r['reason']) ?></p><p>Исходный объём v<?= h($r['baseline_version']) ?>: <?php foreach($versions as $v)if((int)$v['version']===(int)$r['baseline_version'])echo h($v['scope']); ?></p><p>Новый объём: <?= h($r['proposed_scope']) ?></p><h3>Календарный эффект</h3><?php foreach($dates as $d): ?><p><?= h($d['title'].': '.displayDate($d['before']).' → '.displayDate($d['after'])) ?></p><?php endforeach ?><?php if(!$dates): ?><p>Без сдвига сроков.</p><?php endif ?><?php if($commercial&&$r['order_id']!==null): ?><p>Заказ <a href="<?= h(url('clients',['id'=>$r['order_id']])) ?>">#<?= h($r['order_id']) ?></a> · доплата без налогов <?= h(money((int)$r['amount_minor']).' '.$r['currency']) ?> · оплата до <?= h(displayDate($r['payment_due'])) ?></p><?php if($r['decided_at']): ?><p>Решение приглашённого клиента #<?= h($r['decided_guest']) ?>: <?= h($r['decision_note']) ?> · <?= h(gmdate('Y-m-d H:i',(int)$r['decided_at'])) ?> UTC</p><?php endif ?><?php if($r['invoice_id']): ?><p><a href="<?= h(url('invoices',['project'=>$p,'id'=>$r['invoice_id']])) ?>">Дополнительный счёт #<?= h($r['invoice_id']) ?></a></p><?php elseif($r['status']==='applied'&&(int)$r['amount_minor']>0&&$entities): ?><form method="post" class="formgrid"><?php $hidden('pm.invoice') ?><input type="hidden" name="number" value="<?= h($r['number']) ?>"><label>Юрлицо<select name="entity_id"><?php selectOptions(array_column($entities,'name','id')) ?></select></label><button>Создать черновик дополнительного счёта</button></form><?php endif;endif ?>
<?php if($canChange&&in_array($r['status'],['pending','accepted'],true)): ?><form method="post" class="formgrid"><?php $hidden('pm.cancel') ?><input type="hidden" name="number" value="<?= h($r['number']) ?>"><button class="secondary">Отменить запрос</button></form><?php if($r['status']===($client?'accepted':'pending')): ?><form method="post" class="formgrid"><?php $hidden('pm.apply') ?><input type="hidden" name="number" value="<?= h($r['number']) ?>"><label><input type="checkbox" name="confirmed" value="yes" required> Проверил объём и календарный эффект</label><button>Применить новую редакцию</button></form><?php endif;endif ?></details><?php endforeach ?><?php if(!$changes): ?><p>Нет запросов.</p><?php endif ?></section>
<section class="panel"><h2>История базового плана</h2><?php foreach($versions as $v):$snapshot=json_decode($v['calendar_json'],true,512,JSON_THROW_ON_ERROR); ?><details><summary>v<?= h($v['version'].' · '.gmdate('Y-m-d H:i',(int)$v['created_at'])) ?> UTC</summary><p>Автор #<?= h($v['actor_id']) ?></p><p><?= h($v['scope']) ?></p><?php foreach($snapshot['milestones'] as $m): ?><p><?= h($m['title'].' · '.displayDate($m['due_on'])) ?></p><?php endforeach ?></details><?php endforeach ?></section>
